// Des: Turn plain words into a job and its arguments
// Flo: lowercase the words > match a phrase prefix > put the rest in the right slot (url, text, title, to, opt)
// I/O: words (caller) > job name + Args, or null when not understood
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const fld = @import("ut-text-fold.zig");
pub const Slot = enum { none, url, text, title, to, opt };
pub const Rule = struct { pref: []const u8, job: []const u8, slot: Slot };
pub const Cmd = struct { job: []const u8, args: task.Args };
pub const RULES = [_]Rule{ .{ .pref = "open shell", .job = "shell-open", .slot = .none }, .{ .pref = "open ", .job = "page-open", .slot = .url }, .{ .pref = "sign up", .job = "signup", .slot = .none }, .{ .pref = "log in", .job = "login", .slot = .none }, .{ .pref = "login", .job = "login", .slot = .none }, .{ .pref = "log out", .job = "logout", .slot = .none }, .{ .pref = "verify ", .job = "verify-email", .slot = .url }, .{ .pref = "show usage", .job = "usage-view", .slot = .none }, .{ .pref = "show cost", .job = "usage-view", .slot = .none }, .{ .pref = "show limits", .job = "limits-view", .slot = .none }, .{ .pref = "find limit ", .job = "limits-find", .slot = .text }, .{ .pref = "show plan", .job = "plan-view", .slot = .none }, .{ .pref = "show credits", .job = "plan-view", .slot = .none }, .{ .pref = "show invoices", .job = "invoice-list", .slot = .none }, .{ .pref = "show budgets", .job = "budget-list", .slot = .none }, .{ .pref = "show audit", .job = "audit-view", .slot = .none }, .{ .pref = "show instances", .job = "inst-list", .slot = .none }, .{ .pref = "show instance ", .job = "inst-view", .slot = .title }, .{ .pref = "start instance ", .job = "inst-start", .slot = .title }, .{ .pref = "stop instance ", .job = "inst-stop", .slot = .title }, .{ .pref = "reboot instance ", .job = "inst-reboot", .slot = .title }, .{ .pref = "show cpu of ", .job = "metrics-view", .slot = .title }, .{ .pref = "show networks", .job = "vcn-list", .slot = .none }, .{ .pref = "show open ports of ", .job = "secl-view", .slot = .title }, .{ .pref = "show volumes", .job = "vol-list", .slot = .none }, .{ .pref = "show buckets", .job = "bucket-list", .slot = .none }, .{ .pref = "create bucket ", .job = "bucket-create", .slot = .title }, .{ .pref = "show databases", .job = "adb-list", .slot = .none }, .{ .pref = "show keys", .job = "key-list", .slot = .none }, .{ .pref = "show users", .job = "user-list", .slot = .none }, .{ .pref = "invite ", .job = "user-invite", .slot = .to }, .{ .pref = "show policies", .job = "policy-list", .slot = .none }, .{ .pref = "create compartment ", .job = "comp-create", .slot = .title }, .{ .pref = "turn mfa on", .job = "mfa-on", .slot = .none }, .{ .pref = "turn mfa off", .job = "mfa-off", .slot = .none }, .{ .pref = "docs ", .job = "docs-search", .slot = .text }, .{ .pref = "help me ", .job = "feedback-send", .slot = .text } };
pub fn parse(aren: std.mem.Allocator, text: []const u8) !?Cmd { const trimmed = std.mem.trim(u8, text, " \t\r\n"); const low = try fld.foldAlloc(aren, trimmed); for (RULES) |rul| { if (!std.mem.startsWith(u8, low, rul.pref)) continue; const rest = std.mem.trim(u8, trimmed[rul.pref.len..], " "); var cmd: Cmd = .{ .job = rul.job, .args = .{} }; switch (rul.slot) { .none => {}, .url => cmd.args.url = rest, .text => cmd.args.text = rest, .title => cmd.args.title = rest, .to => cmd.args.to = rest, .opt => cmd.args.opt = rest } return cmd; } return null; }
